#include <WiFi.h>
#include <WiFiClientSecure.h>
#include <HTTPClient.h>
#include <Update.h>
#include <Preferences.h>
#include <esp_sleep.h>
#include <esp_ota_ops.h>
#include <esp_system.h>
#include "esp_task_wdt.h"

const char* URL_MAJ  = "https://depot.exemple.fr/sonde/sonde.bin";
const char* URL_DATA = "https://collecteur.exemple.fr/releves";
const char* VERSION  = "1.0.0";
const char* AUTORITE = R"(-----BEGIN CERTIFICATE-----
-----END CERTIFICATE-----)";

constexpr gpio_num_t BROCHE_ALIM_CAPTEUR = GPIO_NUM_26;
constexpr gpio_num_t BROCHE_REVEIL       = GPIO_NUM_33;
constexpr int        ENTREE_BATTERIE     = 34;
constexpr int        ENTREE_CAPTEUR      = 35;
const uint64_t DUREE_VEILLE_US = 30ULL * 60ULL * 1000000ULL;
const size_t   TAILLE_SLOT     = 1966080;

RTC_DATA_ATTR uint32_t compteurReveils = 0;
RTC_DATA_ATTR uint32_t causePrecedente = 0;

Preferences preferences;
String ssid;
String mdp;
String jeton;

void chargerLesSecrets() {
  preferences.begin("secrets", false);
  ssid  = preferences.getString("ssid", "");
  mdp   = preferences.getString("mdp", "");
  jeton = preferences.getString("jeton", "");
  preferences.end();

  if (ssid.isEmpty() || mdp.isEmpty() || jeton.isEmpty()) {
    Serial.println("secrets absents : provisionnez la partition nvs_en_encryption");
    while (true) { esp_task_wdt_reset(); delay(1000); }
  }
}

float lireBatterie() {
  return analogRead(ENTREE_BATTERIE) * 3.3f / 4095.0f * 2.0f;
}

float lireHumidite() {
  digitalWrite(BROCHE_ALIM_CAPTEUR, HIGH);
  delay(100);
  float tension = analogRead(ENTREE_CAPTEUR) * 3.3f / 4095.0f;
  digitalWrite(BROCHE_ALIM_CAPTEUR, LOW);
  return tension;
}

void connecterWifi() {
  WiFi.mode(WIFI_STA);
  WiFi.begin(ssid.c_str(), mdp.c_str());
  uint32_t debut = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - debut < 15000) {
    esp_task_wdt_reset();
    delay(50);
  }
}

bool publier(float humidite, float batterie, const char* etat) {
  if (WiFi.status() != WL_CONNECTED) return false;

  WiFiClientSecure client;
  client.setCACert(AUTORITE);
  HTTPClient https;
  if (!https.begin(client, URL_DATA)) return false;

  https.addHeader("Content-Type", "application/json");
  https.addHeader("Authorization", String("Bearer ") + jeton);

  String corps = String("{\"version\":\"") + VERSION +
                 "\",\"hum\":" + humidite +
                 ",\"bat\":" + batterie +
                 ",\"reveils\":" + compteurReveils +
                 ",\"cause\":" + causePrecedente +
                 ",\"etat\":\"" + etat + "\"}";

  int code = https.POST(corps);
  https.end();
  return code >= 200 && code < 300;
}

bool mettreAJourSiDisponible() {
  if (WiFi.status() != WL_CONNECTED) return false;
  if (lireBatterie() < 3.5f) return false;

  WiFiClientSecure client;
  client.setCACert(AUTORITE);
  HTTPClient https;
  if (!https.begin(client, URL_MAJ)) return false;

  https.addHeader("Authorization", String("Bearer ") + jeton);
  https.addHeader("X-Version-Installee", VERSION);
  if (https.GET() != 200) { https.end(); return false; }

  int taille = https.getSize();
  if (taille <= 0 || (size_t)taille > TAILLE_SLOT) { https.end(); return false; }
  if (!Update.begin(taille)) { https.end(); return false; }

  size_t ecrit = Update.writeStream(*https.getStreamPtr());
  https.end();
  if (ecrit != (size_t)taille) { Update.abort(); return false; }
  if (!Update.end()) return false;

  Serial.println("image ecrite, bascule au redemarrage");
  return true;
}

void setup() {
  Serial.begin(115200);

  esp_task_wdt_config_t cfg = {};
  cfg.timeout_ms = 10000;
  cfg.idle_core_mask = 0;
  cfg.trigger_panic = true;
  esp_task_wdt_reconfigure(&cfg);
  esp_task_wdt_add(nullptr);

  chargerLesSecrets();

  gpio_deep_sleep_hold_dis();
  pinMode(BROCHE_ALIM_CAPTEUR, OUTPUT);
  digitalWrite(BROCHE_ALIM_CAPTEUR, LOW);
  pinMode(BROCHE_REVEIL, INPUT_PULLUP);

  compteurReveils++;
  causePrecedente = (uint32_t)esp_sleep_get_wakeup_cause();

  Serial.printf("demarrage %s, reveil numero %u, cause %u\n",
                VERSION, compteurReveils, causePrecedente);
}

void loop() {
  esp_task_wdt_reset();

  float humidite = lireHumidite();
  float batterie = lireBatterie();
  bool capteurValide = (humidite > 0.0f && humidite < 3.3f) && (batterie > 3.0f);

  connecterWifi();
  bool publie = publier(humidite, batterie, "mesure");

  if (mettreAJourSiDisponible()) {
    Serial.flush();
    ESP.restart();
  }

  if (publie) publier(humidite, batterie, "a-jour");

  // Un reseau indisponible ne doit pas declencher de retour arriere :
  // seuls les controles locaux decident de la validite de la version.
  if (capteurValide) esp_ota_mark_app_valid_cancel_rollback();

  WiFi.mode(WIFI_OFF);

  gpio_hold_en(BROCHE_ALIM_CAPTEUR);
  gpio_deep_sleep_hold_en();
  esp_sleep_enable_timer_wakeup(DUREE_VEILLE_US);
  esp_sleep_enable_ext0_wakeup(BROCHE_REVEIL, 0);

  Serial.printf("dormir 30 min, hum %.2f V, bat %.2f V\n", humidite, batterie);
  Serial.flush();
  esp_deep_sleep_start();
}
